function getEnhancedNextLayout(projectName, profile, analysis) {
  const title = String(analysis?.seoTitle || `${projectName} | ${profile.name}`).replace(/'/g, "\\'");
  const description = String(analysis?.seoDescription || profile.tagline || `Aplikasi ${profile.name} modern.`).replace(/'/g, "\\'");
  return `import './globals.css';\n\nexport const metadata = { title: '${title}', description: '${description}', keywords: ['${profile.name.replace(/'/g, "\\'")}', 'aplikasi bisnis', 'dashboard'], robots: { index: true, follow: true }, openGraph: { title: '${title}', description: '${description}', type: 'website', locale: 'id_ID' } };\nexport const viewport = { themeColor: '#08111f' };\nexport default function RootLayout({ children }) { return <html lang="id"><body>{children}</body></html>; }\n`;
}

function getMigrationAudit(projectName, profile, analysis) {
  const list = values => (values?.length ? values.map(value => `- ${value}`).join('\n') : '- Tidak ada catatan tambahan.');
  return `# Migration Audit — ${projectName}\n\n## Profil\n\n- Jenis aplikasi: ${profile.name}\n- Modul: ${(profile.modules || []).map(module => module.name).join(', ')}\n\n## Ringkasan AI\n\n${analysis?.summary || 'AI tidak dikonfigurasi; gunakan checklist template bawaan.'}\n\n## Arah UI\n\n${analysis?.uiDirection || 'Dashboard SaaS responsif dengan dark mode, analitik, dan transisi halus.'}\n\n## Rencana backend\n\n${analysis?.backendPlan || 'Ganti penyimpanan browser dengan database dan autentikasi server-side sebelum produksi.'}\n\n## Risiko\n\n${list(analysis?.risks)}\n\n## Checklist tes\n\n${list(analysis?.testChecklist || ['npm run build', 'Uji login dan modul', 'Uji layar mobile', 'Hubungkan database produksi sebelum go-live'])}\n`;
}

function getEnhancedNextPage() {
  return `'use client';\nimport { useEffect, useMemo, useState } from 'react';\nimport { APP } from '../lib/app-config';\nconst storage='next-migration-records'; const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);\nexport default function Home(){const modules=APP.profile.modules||[];const [user,setUser]=useState(null);const [view,setView]=useState('dashboard');const [rows,setRows]=useState([]);const [theme,setTheme]=useState('dark');const active=modules.find(x=>x.id===view);useEffect(()=>{try{setRows(JSON.parse(localStorage.getItem(storage)||'[]'))}catch{}},[]);useEffect(()=>{document.documentElement.dataset.theme=theme},[theme]);const numbers=rows.map(r=>Number(r.total||r.nominal||r.harga||r.biaya||0));const income=numbers.reduce((a,b)=>a+b,0);const byModule=modules.map(m=>({name:m.name,total:rows.filter(r=>r.moduleId===m.id).length}));function login(e){e.preventDefault();const f=new FormData(e.currentTarget),name=f.get('username');setUser({name:name==='Admin'?'Administrator':name,role:name==='Admin'?'admin':'member'})}function save(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const next=[{id:crypto.randomUUID(),moduleId:active.id,createdAt:new Date().toLocaleString('id-ID'),...data},...rows];setRows(next);localStorage.setItem(storage,JSON.stringify(next));e.currentTarget.reset()}if(!user)return <main className="login"><section className="login-hero"><p>PREMIUM NEXT.JS</p><h1>{APP.name}</h1><span>{APP.profile.tagline}</span><div className="orb one"/><div className="orb two"/></section><form className="login-card" onSubmit={login}><p className="eyebrow">MIGRASI DARI GAS</p><h2>Selamat datang</h2><p>Pengalaman baru yang lebih cepat dan modern.</p><input name="username" defaultValue="Admin" placeholder="Username" required/><input name="password" type="password" placeholder="Password" required/><button>Masuk ke Dashboard</button><small>Demo lokal: Admin / Admin123</small></form></main>;const nav=modules.filter(m=>!m.adminOnly||user.role==='admin');return <main className="shell"><aside><div className="brand"><span className="brand-mark">◈</span><div><b>{APP.name}</b><small>{APP.profile.name}</small></div></div><nav><button className={view==='dashboard'?'active':''} onClick={()=>setView('dashboard')}>◫ Dashboard</button>{nav.map(m=><button key={m.id} className={view===m.id?'active':''} onClick={()=>setView(m.id)}>◇ {m.name}</button>)}</nav><div className="account"><span className="avatar">{user.name[0]}</span><div><b>{user.name}</b><small>{user.role==='admin'?'Administrator':'User'}</small></div><button aria-label="Keluar" onClick={()=>setUser(null)}>↪</button></div></aside><section className="workspace"><header><div><p className="eyebrow">{APP.profile.name}</p><h1>{active?active.name:'Ringkasan bisnis'}</h1><span>{active?'Kelola data dan aktivitas dari satu tempat.':'Pantau performa aplikasi secara real-time.'}</span></div><div className="header-actions"><button className="ghost" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?'☀ Terang':'◐ Gelap'}</button><button className="profile">{user.name[0]}</button></div></header>{!active?<Dashboard rows={rows} income={income} byModule={byModule} setView={setView}/>:<Module active={active} rows={rows.filter(r=>r.moduleId===active.id)} save={save}/>}<p className="notice">Data migrasi awal disimpan di browser. Hubungkan database dan autentikasi server-side sebelum penggunaan produksi multi-user.</p></section></main>}\nfunction Dashboard({rows,income,byModule,setView}){const max=Math.max(...byModule.map(x=>x.total),1);return <><section className="metrics"><article><small>Total aktivitas</small><b>{rows.length}</b><span>Semua modul</span></article><article><small>Nilai tercatat</small><b>{money(income)}</b><span>Akumulasi data numerik</span></article><article><small>Modul aktif</small><b>{byModule.filter(x=>x.total).length}</b><span>Dari {byModule.length} modul</span></article></section><section className="overview"><article className="panel chart"><div className="panel-head"><div><p className="eyebrow">ANALITIK</p><h2>Aktivitas per modul</h2></div></div><div className="bars">{byModule.map((item,i)=><button key={item.name} onClick={()=>setView(item.name===item.name?'dashboard':'dashboard')}><span style={{height:(item.total/max*100||4)+'%'}}/><small>{item.name}</small><b>{item.total}</b></button>)}</div></article><article className="panel recent"><div className="panel-head"><h2>Aktivitas terbaru</h2><span>{rows.length} data</span></div>{rows.slice(0,5).map(r=><div className="recent-row" key={r.id}><span className="pulse"/><div><b>{Object.values(r).find(v=>typeof v==='string'&&v!==r.createdAt&&v!==r.moduleId)||'Data baru'}</b><small>{r.createdAt}</small></div></div>)}{!rows.length&&<p className="empty">Belum ada aktivitas. Pilih menu untuk menambah data.</p>}</article></section></>}\nfunction Module({active,rows,save}){return <section className="module-grid"><form className="panel form" onSubmit={save}><div className="panel-head"><div><p className="eyebrow">INPUT DATA</p><h2>Tambah {active.name}</h2></div></div>{active.fields.map(f=><label key={f.key}>{f.label}{f.type==='select'?<select name={f.key} required>{f.options.map(o=><option key={o}>{o}</option>)}</select>:<input name={f.key} type={f.type==='datetime-local'?'datetime-local':f.type} required/>}</label>)}<button>Simpan Data <span>→</span></button></form><article className="panel records"><div className="panel-head"><div><p className="eyebrow">DATA TERBARU</p><h2>{active.name}</h2></div><span className="badge">{rows.length} data</span></div><div className="table-wrap"><table><thead><tr>{active.fields.map(f=><th key={f.key}>{f.label}</th>)}<th>Dibuat</th></tr></thead><tbody>{rows.length?rows.slice().reverse().map(r=><tr key={r.id}>{active.fields.map(f=><td key={f.key}>{r[f.key]||'-'}</td>)}<td>{r.createdAt}</td></tr>):<tr><td colSpan={active.fields.length+1} className="empty">Belum ada data.</td></tr>}</tbody></table></div></article></section>}\n`;
}

function getDesignTemplateStyles(design) {
  const accent = /^#[0-9a-f]{6}$/i.test(design?.accent || '') ? design.accent : '#60a5fa';
  const accent2 = /^#[0-9a-f]{6}$/i.test(design?.accent2 || '') ? design.accent2 : '#a78bfa';
  const layout = design?.layout || 'sidebar';
  const landing = design?.landing || 'split';
  const layoutCss = layout === 'topbar'
    ? `.layout-topbar{display:block}.layout-topbar aside{width:100%;min-height:auto;flex-direction:row;align-items:center;gap:1rem;padding:.8rem clamp(1rem,3vw,3rem);border-right:0;border-bottom:1px solid var(--line)}.layout-topbar aside nav{display:flex;overflow:auto;margin:0;flex:1}.layout-topbar .account{margin:0;padding:0;border:0;min-width:max-content}.layout-topbar .workspace{max-width:1440px;margin:auto}`
    : layout === 'rail'
      ? `.layout-rail aside{width:15rem;padding:1rem .8rem;background:linear-gradient(180deg,#0b1628,#111d34)}.layout-rail .brand{padding:.8rem .55rem}.layout-rail nav{gap:.45rem}.layout-rail nav button{display:flex;align-items:center;min-height:3rem;padding:.75rem .85rem;font-size:.9rem}.layout-rail .account{padding:.9rem .55rem}.layout-rail .account button{display:grid;place-items:center;min-width:2.25rem}`
      : '';
  const landingCss = landing === 'centered'
    ? `.landing-centered{grid-template-columns:1fr;background:radial-gradient(circle at 50% 8%,${accent}55,transparent 30rem),var(--bg)}.landing-centered .login-hero{min-height:38vh;align-items:center;text-align:center;background:linear-gradient(135deg,#0b1628,${accent}99,#0b1628)}.landing-centered .login-card{margin:-4rem auto 3rem;z-index:2;transform:none}`
    : landing === 'editorial'
      ? `.landing-editorial .login-hero{background:linear-gradient(135deg,#130d20,${accent}cc,${accent2}bb)}.landing-editorial .login-hero h1{font-family:Georgia,serif;letter-spacing:-.075em}.landing-editorial .login-card{border-radius:.9rem}`
      : '';
  return `:root{--accent:${accent};--accent2:${accent2}}.login-hero{background:linear-gradient(145deg,#0b1628,${accent},${accent2})}.brand-mark,.avatar,.profile{background:linear-gradient(135deg,${accent},${accent2})}.bars button span{background:linear-gradient(180deg,${accent},${accent2})}${layoutCss}${landingCss}`;
}

function getEnhancedNextStyles() {
  return `:root{--bg:#08111f;--surface:#101c31;--surface2:#172845;--line:#2a4063;--text:#eff6ff;--muted:#91a4c2;--accent:#60a5fa;--accent2:#a78bfa}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 88% 6%,#2563eb22,transparent 25rem),radial-gradient(circle at 12% 90%,#7c3aed18,transparent 28rem),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui}button,input,select{font:inherit}button{border:0;cursor:pointer}.login{min-height:100vh;display:grid;grid-template-columns:1.2fr .8fr}.login-hero{position:relative;overflow:hidden;padding:clamp(3rem,8vw,8rem);display:flex;flex-direction:column;justify-content:center;background:linear-gradient(145deg,#0b2144,#1d4ed8,#7c3aed);background-size:180% 180%;animation:gradient 14s ease infinite}.login-hero h1{font-size:clamp(3.2rem,7vw,6.5rem);margin:.5rem 0;letter-spacing:-.06em}.login-hero span{max-width:34rem;color:#dbeafe;font-size:1.1rem;line-height:1.8}.orb{position:absolute;border-radius:50%;filter:blur(2px);opacity:.4;animation:float 8s ease-in-out infinite}.orb.one{width:15rem;height:15rem;background:#38bdf8;right:12%;top:12%}.orb.two{width:9rem;height:9rem;background:#c084fc;left:18%;bottom:12%;animation-delay:-3s}.login-card{align-self:center;width:min(27rem,calc(100% - 3rem));margin:auto;padding:2rem;border:1px solid var(--line);border-radius:1.75rem;background:#0d182b;box-shadow:0 30px 90px #0008;animation:reveal .6s ease both}.eyebrow{margin:0;color:var(--accent);font-size:.72rem;font-weight:800;letter-spacing:.13em}.login-card h2{font-size:2rem;margin:.35rem 0}.login-card p,.login-card small,.workspace header span,.notice,small{color:var(--muted)}input,select{width:100%;margin:.45rem 0 1rem;padding:.85rem .95rem;border:1px solid var(--line);border-radius:.8rem;background:#091426;color:var(--text)}button{padding:.82rem 1rem;border-radius:.8rem;background:linear-gradient(135deg,var(--accent),#2563eb);color:#fff;font-weight:750;transition:transform .2s ease,filter .2s ease,box-shadow .2s ease}button:hover{transform:translateY(-2px);filter:brightness(1.08);box-shadow:0 12px 28px #2563eb44}.shell{min-height:100vh;display:flex}aside{width:17.5rem;padding:1.25rem;background:#0b1628cc;border-right:1px solid var(--line);display:flex;flex-direction:column;backdrop-filter:blur(14px)}.brand{display:flex;gap:.8rem;align-items:center;padding:.7rem}.brand-mark,.avatar,.profile{display:grid;place-items:center;width:2.5rem;height:2.5rem;border-radius:.85rem;background:linear-gradient(135deg,#60a5fa,#7c3aed);color:white}.brand div{display:grid;gap:.15rem}.brand small{font-size:.75rem}nav{display:grid;gap:.3rem;margin-top:2rem}nav button{background:transparent;text-align:left;color:#cad8ee}nav button.active,nav button:hover{background:var(--surface2);box-shadow:inset 3px 0 0 var(--accent)}.account{display:flex;gap:.65rem;align-items:center;margin-top:auto;padding:.9rem .5rem;border-top:1px solid var(--line)}.account div{display:grid;gap:.1rem;flex:1}.account button,.ghost{background:var(--surface2);padding:.55rem}.workspace{flex:1;padding:clamp(1rem,3vw,3rem)}header{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start;margin-bottom:2rem}header h1{margin:.25rem 0;font-size:clamp(2rem,4vw,3.25rem);letter-spacing:-.04em}.header-actions{display:flex;gap:.7rem}.profile{border:1px solid #ffffff22}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.metrics article,.panel{border:1px solid var(--line);background:linear-gradient(160deg,#14213a,#0e192c);border-radius:1.35rem;box-shadow:0 18px 40px #0002}.metrics article{padding:1.35rem;animation:reveal .55s ease both}.metrics article:nth-child(2){animation-delay:.07s}.metrics article:nth-child(3){animation-delay:.14s}.metrics small,.metrics span{display:block;color:var(--muted)}.metrics b{display:block;margin:.45rem 0;font-size:clamp(1.55rem,3vw,2.3rem)}.overview,.module-grid{display:grid;grid-template-columns:1.5fr .9fr;gap:1rem;margin-top:1rem}.panel{padding:1.35rem}.panel-head{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start}.panel h2{margin:.25rem 0;font-size:1.2rem}.chart{min-height:20rem}.bars{height:14rem;display:flex;align-items:flex-end;gap:.8rem;margin-top:1rem}.bars button{height:100%;flex:1;padding:0;background:transparent;display:grid;grid-template-rows:1fr auto auto;gap:.45rem;align-items:end}.bars button span{width:100%;min-height:.5rem;border-radius:.7rem .7rem .2rem .2rem;background:linear-gradient(180deg,#60a5fa,#7c3aed);animation:bar .8s cubic-bezier(.2,.8,.2,1) both}.bars small{font-size:.68rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}.bars b{font-size:.8rem}.recent-row{display:flex;gap:.75rem;padding:.9rem 0;border-bottom:1px solid var(--line)}.recent-row div{display:grid;gap:.25rem}.pulse{width:.65rem;height:.65rem;margin-top:.35rem;border-radius:99px;background:#34d399;box-shadow:0 0 0 5px #34d39922}.form label{display:block;margin:.9rem 0;font-size:.88rem;font-weight:700}.form button{width:100%;margin-top:.5rem}.form button span{float:right}.records{min-width:0}.badge{padding:.4rem .65rem;border-radius:99px;background:#60a5fa18;color:#93c5fd;font-size:.78rem}.table-wrap{overflow:auto;margin-top:1rem}table{width:100%;min-width:42rem;border-collapse:collapse}th,td{padding:1rem;text-align:left;border-bottom:1px solid var(--line);font-size:.87rem}th{color:var(--muted);font-size:.7rem;text-transform:uppercase;letter-spacing:.05em}.empty{color:var(--muted);text-align:center;padding:2rem}.notice{margin:1rem 0;font-size:.82rem}@keyframes gradient{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}@keyframes float{50%{transform:translateY(-22px) translateX(12px)}}@keyframes reveal{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}@keyframes bar{from{transform:scaleY(.1);transform-origin:bottom}to{transform:scaleY(1);transform-origin:bottom}}[data-theme=light]{--bg:#eef4ff;--surface:#fff;--surface2:#e4edff;--line:#c7d5ed;--text:#12213a;--muted:#58708f;--accent:#2563eb} [data-theme=light] body{background:#eef4ff}[data-theme=light] aside,[data-theme=light] .login-card{background:#fff}[data-theme=light] .panel,[data-theme=light] .metrics article{background:#fff}[data-theme=light] input,[data-theme=light] select{background:#f8fbff;color:#12213a}@media(max-width:900px){.login{grid-template-columns:1fr}.login-hero{min-height:38vh}.shell{display:block}aside{width:100%;min-height:auto}nav{display:flex;overflow:auto;margin:1rem 0}.account{display:none}.metrics,.overview,.module-grid{grid-template-columns:1fr}header{display:block}.header-actions{margin-top:1rem}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}\n`;
}
